//! Handles stratification of Datalog programs

use petgraph::{algo, graphmap::DiGraphMap};
use std::collections::{HashMap, HashSet};
use std::slice::Iter;
use syn::Ident;

pub struct Strata {
    list: Vec<Vec<Ident>>,
    index: HashMap<Ident, usize>,
}

impl Strata {
    pub fn new(relations: HashSet<Ident>, dependencies: HashSet<(&Ident, &Ident)>) -> Self {
        // Build the dependency graph, where an edge from a goal relation to a
        // fact relation means that the goal is derived from that fact.
        let mut graph: DiGraphMap<&Ident, ()> = DiGraphMap::new();
        for relation in &relations {
            graph.add_node(relation);
        }
        for &(goal, fact) in &dependencies {
            graph.add_edge(goal, fact, ());
        }

        // Each stratum is a strongly connected component of the dependency
        // graph, since mutually recursive relations need to be evaluated
        // together. Tarjan strongly connected components are returned in
        // reverse topological order, so every relation ends up in a stratum
        // that comes at or after all of the relations that it depends on.
        let sccs = algo::tarjan_scc(&graph);

        let mut list = Vec::with_capacity(sccs.len());
        let mut index = HashMap::new();
        for (i, scc) in sccs.into_iter().enumerate() {
            let stratum: Vec<Ident> = scc.into_iter().cloned().collect();
            for relation in &stratum {
                index.insert(relation.clone(), i);
            }
            list.push(stratum);
        }

        Self { list, index }
        }

    pub fn iter(&self) -> Iter<'_, Vec<Ident>> {
        self.list.iter()
    }

    pub fn find_relation(&self, rel: &Ident) -> usize {
        *self.index.get(rel).expect("key not found in stratum index")
    }
}

