#[cfg(test)]
mod carve_strata_tests {
    use super::Strata;
    use proc_macro2::Span;
    use std::collections::{HashMap, HashSet};
    use syn::Ident;

    fn id(name: &str) -> Ident {
        Ident::new(name, Span::call_site())
    }

    fn build(rels: &[&str], deps: &[(&str, &str)]) -> Strata {
        let names: HashMap<String, Ident> =
            rels.iter().map(|r| (r.to_string(), id(r))).collect();
        let relations: HashSet<Ident> = names.values().cloned().collect();
        let dependencies: HashSet<(&Ident, &Ident)> =
            deps.iter().map(|(a, b)| (&names[*a], &names[*b])).collect();
        Strata::new(relations, dependencies)
    }

    fn check_partition(strata: &Strata, rels: &[&str]) {
        let mut seen: Vec<String> = Vec::new();
        for (i, stratum) in strata.iter().enumerate() {
            for rel in stratum {
                seen.push(rel.to_string());
                assert_eq!(strata.find_relation(rel), i);
            }
        }
        seen.sort();
        let mut expected: Vec<String> = rels.iter().map(|r| r.to_string()).collect();
        expected.sort();
        assert_eq!(seen, expected, "every relation appears in exactly one stratum");
    }

    #[test]
    fn independent_relations() {
        let rels = ["Foo", "Bar", "Baz"];
        let strata = build(&rels, &[]);
        check_partition(&strata, &rels);
        assert_eq!(strata.iter().count(), 3);
        for stratum in strata.iter() {
            assert_eq!(stratum.len(), 1);
        }
    }

    #[test]
    fn empty_program() {
        let strata = build(&[], &[]);
        assert_eq!(strata.iter().count(), 0);
    }

    #[test]
    fn linear_chain_is_reverse_topological() {
        let rels = ["Foo", "Bar", "Baz"];
        let strata = build(&rels, &[("Foo", "Bar"), ("Bar", "Baz")]);
        check_partition(&strata, &rels);
        assert_eq!(strata.iter().count(), 3);
        let foo = strata.find_relation(&id("Foo"));
        let bar = strata.find_relation(&id("Bar"));
        let baz = strata.find_relation(&id("Baz"));
        assert!(baz < bar, "dependencies come first");
        assert!(bar < foo, "dependencies come first");
    }

    #[test]
    fn mutual_recursion_shares_a_stratum() {
        let rels = ["Tc", "Edge", "Path"];
        let strata = build(&rels, &[("Tc", "Path"), ("Path", "Tc"), ("Tc", "Edge")]);
        check_partition(&strata, &rels);
        assert_eq!(strata.iter().count(), 2);
        let tc = strata.find_relation(&id("Tc"));
        let path = strata.find_relation(&id("Path"));
        let edge = strata.find_relation(&id("Edge"));
        assert_eq!(tc, path, "mutually recursive relations are in one stratum");
        assert!(edge < tc);
        let stratum = strata.iter().nth(tc).unwrap();
        assert_eq!(stratum.len(), 2);
    }

    #[test]
    fn self_recursion_is_one_stratum() {
        let rels = ["Tc", "Edge"];
        let strata = build(&rels, &[("Tc", "Tc"), ("Tc", "Edge")]);
        check_partition(&strata, &rels);
        assert_eq!(strata.iter().count(), 2);
        assert!(strata.find_relation(&id("Edge")) < strata.find_relation(&id("Tc")));
        assert_eq!(strata.iter().nth(strata.find_relation(&id("Tc"))).unwrap().len(), 1);
    }

    #[test]
    fn diamond_orders_all_dependencies_first() {
        let rels = ["Top", "Left", "Right", "Bottom"];
        let deps = [
            ("Top", "Left"),
            ("Top", "Right"),
            ("Left", "Bottom"),
            ("Right", "Bottom"),
        ];
        let strata = build(&rels, &deps);
        check_partition(&strata, &rels);
        assert_eq!(strata.iter().count(), 4);
        for (goal, fact) in deps.iter() {
            assert!(
                strata.find_relation(&id(fact)) < strata.find_relation(&id(goal)),
                "acyclic dependency must land in an earlier stratum"
            );
        }
    }

    #[test]
    fn every_dependency_is_ordered_before_its_goal() {
        let rels = ["A", "B", "C", "D", "E"];
        let deps = [("A", "B"), ("B", "C"), ("C", "B"), ("D", "A"), ("E", "D")];
        let strata = build(&rels, &deps);
        check_partition(&strata, &rels);
        for (goal, fact) in deps.iter() {
            assert!(strata.find_relation(&id(fact)) <= strata.find_relation(&id(goal)));
        }
        assert_eq!(strata.find_relation(&id("B")), strata.find_relation(&id("C")));
        assert!(strata.find_relation(&id("A")) > strata.find_relation(&id("B")));
    }

    #[test]
    fn relations_without_rules_are_still_stratified() {
        let rels = ["Lonely", "Goal", "Source"];
        let strata = build(&rels, &[("Goal", "Source")]);
        check_partition(&strata, &rels);
        assert_eq!(strata.iter().count(), 3);
        strata.find_relation(&id("Lonely"));
    }

    #[test]
    #[should_panic(expected = "key not found in stratum index")]
    fn unknown_relation_panics() {
        let strata = build(&["Foo"], &[]);
        strata.find_relation(&id("Missing"));
    }
}
