        assert!(strata.find_relation(&id(stringify!(A))) > b);
        assert!(strata.find_relation(&id(stringify!(E))) > strata.find_relation(&id(stringify!(D))));
    }

    #[test]
    fn relations_without_any_rule_are_still_stratified() {
        let rels = names![Lonely, Goal, Source];
        let strata = build(&rels, &deps![(Goal, Source)]);
        check_partition(&strata, &rels);
        assert_eq!(strata.iter().count(), 3);
        strata.find_relation(&id(stringify!(Lonely)));
    }

    #[test]
    #[should_panic]
    fn find_relation_panics_on_unknown_relation() {
        let strata = build(&names![Foo], &[]);
        strata.find_relation(&id(stringify!(Missing)));
    }
